macro_rules! deps {
    () => {
        CompatSink!();
        Either!();
        StreamExt!();
        Send!();
        Close!();
        Feed!();
        Sink!();
        Flush!();
    };
}

macro_rules! SinkExt {
    () => {
        deps!();
        # [doc = " An extension trait for `Sink`s that provides a variety of convenient"] # [doc = " combinator functions."] pub trait SinkExt < Item > : Sink < Item > { # [doc = " Composes a function *in front of* the sink."] # [doc = ""] # [doc = " This adapter produces a new sink that passes each value through the"] # [doc = " given function `f` before sending it to `self`."] # [doc = ""] # [doc = " To process each value, `f` produces a *future*, which is then polled to"] # [doc = " completion before passing its result down to the underlying sink. If the"] # [doc = " future produces an error, that error is returned by the new sink."] # [doc = ""] # [doc = " Note that this function consumes the given sink, returning a wrapped"] # [doc = " version, much like `Iterator::map`."] fn with < U , Fut , F , E > (self , f : F) -> With < Self , Item , U , Fut , F > where F : FnMut (U) -> Fut , Fut : Future < Output = Result < Item , E > > , E : From < Self :: Error > , Self : Sized , { assert_sink :: < U , E , _ > (With :: new (self , f)) } # [doc = " Composes a function *in front of* the sink."] # [doc = ""] # [doc = " This adapter produces a new sink that passes each value through the"] # [doc = " given function `f` before sending it to `self`."] # [doc = ""] # [doc = " To process each value, `f` produces a *stream*, of which each value"] # [doc = " is passed to the underlying sink. A new value will not be accepted until"] # [doc = " the stream has been drained"] # [doc = ""] # [doc = " Note that this function consumes the given sink, returning a wrapped"] # [doc = " version, much like `Iterator::flat_map`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # futures::executor::block_on(async {"] # [doc = " use futures::channel::mpsc;"] # [doc = " use futures::sink::SinkExt;"] # [doc = " use futures::stream::{self, StreamExt};"] # [doc = ""] # [doc = " let (tx, rx) = mpsc::channel(5);"] # [doc = ""] # [doc = " let mut tx = tx.with_flat_map(|x| {"] # [doc = "     stream::iter(vec![Ok(42); x])"] # [doc = " });"] # [doc = ""] # [doc = " tx.send(5).await.unwrap();"] # [doc = " drop(tx);"] # [doc = " let received: Vec<i32> = rx.collect().await;"] # [doc = " assert_eq!(received, vec![42, 42, 42, 42, 42]);"] # [doc = " # });"] # [doc = " ```"] fn with_flat_map < U , St , F > (self , f : F) -> WithFlatMap < Self , Item , U , St , F > where F : FnMut (U) -> St , St : Stream < Item = Result < Item , Self :: Error > > , Self : Sized , { assert_sink :: < U , Self :: Error , _ > (WithFlatMap :: new (self , f)) } # [doc = " Transforms the error returned by the sink."] fn sink_map_err < E , F > (self , f : F) -> SinkMapErr < Self , F > where F : FnOnce (Self :: Error) -> E , Self : Sized , { assert_sink :: < Item , E , _ > (SinkMapErr :: new (self , f)) } # [doc = " Map this sink's error to a different error type using the `Into` trait."] # [doc = ""] # [doc = " If wanting to map errors of a `Sink + Stream`, use `.sink_err_into().err_into()`."] fn sink_err_into < E > (self) -> err_into :: SinkErrInto < Self , Item , E > where Self : Sized , Self :: Error : Into < E > , { assert_sink :: < Item , E , _ > (SinkErrInto :: new (self)) } # [doc = " Adds a fixed-size buffer to the current sink."] # [doc = ""] # [doc = " The resulting sink will buffer up to `capacity` items when the"] # [doc = " underlying sink is unwilling to accept additional items. Calling `flush`"] # [doc = " on the buffered sink will attempt to both empty the buffer and complete"] # [doc = " processing on the underlying sink."] # [doc = ""] # [doc = " Note that this function consumes the given sink, returning a wrapped"] # [doc = " version, much like `Iterator::map`."] # [doc = ""] # [doc = " This method is only available when the `std` or `alloc` feature of this"] # [doc = " library is activated, and it is activated by default."] # [cfg (feature = "alloc")] fn buffer (self , capacity : usize) -> Buffer < Self , Item > where Self : Sized , { assert_sink :: < Item , Self :: Error , _ > (Buffer :: new (self , capacity)) } # [doc = " Close the sink."] fn close (& mut self) -> Close < '_ , Self , Item > where Self : Unpin , { assert_future :: < Result < () , Self :: Error > , _ > (Close :: new (self)) } # [doc = " Fanout items to multiple sinks."] # [doc = ""] # [doc = " This adapter clones each incoming item and forwards it to both this as well as"] # [doc = " the other sink at the same time."] fn fanout < Si > (self , other : Si) -> Fanout < Self , Si > where Self : Sized , Item : Clone , Si : Sink < Item , Error = Self :: Error > , { assert_sink :: < Item , Self :: Error , _ > (Fanout :: new (self , other)) } # [doc = " Flush the sink, processing all pending items."] # [doc = ""] # [doc = " This adapter is intended to be used when you want to stop sending to the sink"] # [doc = " until all current requests are processed."] fn flush (& mut self) -> Flush < '_ , Self , Item > where Self : Unpin , { assert_future :: < Result < () , Self :: Error > , _ > (Flush :: new (self)) } # [doc = " A future that completes after the given item has been fully processed"] # [doc = " into the sink, including flushing."] # [doc = ""] # [doc = " Note that, **because of the flushing requirement, it is usually better"] # [doc = " to batch together items to send via `feed` or `send_all`,"] # [doc = " rather than flushing between each item.**"] fn send (& mut self , item : Item) -> Send < '_ , Self , Item > where Self : Unpin , { assert_future :: < Result < () , Self :: Error > , _ > (Send :: new (self , item)) } # [doc = " A future that completes after the given item has been received"] # [doc = " by the sink."] # [doc = ""] # [doc = " Unlike `send`, the returned future does not flush the sink."] # [doc = " It is the caller's responsibility to ensure all pending items"] # [doc = " are processed, which can be done via `flush` or `close`."] fn feed (& mut self , item : Item) -> Feed < '_ , Self , Item > where Self : Unpin , { assert_future :: < Result < () , Self :: Error > , _ > (Feed :: new (self , item)) } # [doc = " A future that completes after the given stream has been fully processed"] # [doc = " into the sink, including flushing."] # [doc = ""] # [doc = " This future will drive the stream to keep producing items until it is"] # [doc = " exhausted, sending each item to the sink. It will complete once both the"] # [doc = " stream is exhausted, the sink has received all items, and the sink has"] # [doc = " been flushed. Note that the sink is **not** closed. If the stream produces"] # [doc = " an error, that error will be returned by this future without flushing the sink."] # [doc = ""] # [doc = " Doing `sink.send_all(stream)` is roughly equivalent to"] # [doc = " `stream.forward(sink)`. The returned future will exhaust all items from"] # [doc = " `stream` and send them to `self`."] fn send_all < St > (& mut self , stream : St) -> SendAll < '_ , Self , St > where St : Stream < Item = Result < Item , Self :: Error > > , Self : Unpin , { assert_future :: < Result < () , Self :: Error > , _ > (SendAll :: new (self , stream)) } # [doc = " Wrap this sink in an `Either` sink, making it the left-hand variant"] # [doc = " of that `Either`."] # [doc = ""] # [doc = " This can be used in combination with the `right_sink` method to write `if`"] # [doc = " statements that evaluate to different streams in different branches."] fn left_sink < Si2 > (self) -> Either < Self , Si2 > where Si2 : Sink < Item , Error = Self :: Error > , Self : Sized , { assert_sink :: < Item , Self :: Error , _ > (Either :: Left (self)) } # [doc = " Wrap this stream in an `Either` stream, making it the right-hand variant"] # [doc = " of that `Either`."] # [doc = ""] # [doc = " This can be used in combination with the `left_sink` method to write `if`"] # [doc = " statements that evaluate to different streams in different branches."] fn right_sink < Si1 > (self) -> Either < Si1 , Self > where Si1 : Sink < Item , Error = Self :: Error > , Self : Sized , { assert_sink :: < Item , Self :: Error , _ > (Either :: Right (self)) } # [doc = " Wraps a [`Sink`] into a sink compatible with libraries using"] # [doc = " futures 0.1 `Sink`. Requires the `compat` feature to be enabled."] # [cfg (feature = "compat")] # [cfg_attr (docsrs , doc (cfg (feature = "compat")))] fn compat (self) -> CompatSink < Self , Item > where Self : Sized + Unpin , { CompatSink :: new (self) } # [doc = " A convenience method for calling [`Sink::poll_ready`] on [`Unpin`]"] # [doc = " sink types."] fn poll_ready_unpin (& mut self , cx : & mut Context < '_ >) -> Poll < Result < () , Self :: Error > > where Self : Unpin , { Pin :: new (self) . poll_ready (cx) } # [doc = " A convenience method for calling [`Sink::start_send`] on [`Unpin`]"] # [doc = " sink types."] fn start_send_unpin (& mut self , item : Item) -> Result < () , Self :: Error > where Self : Unpin , { Pin :: new (self) . start_send (item) } # [doc = " A convenience method for calling [`Sink::poll_flush`] on [`Unpin`]"] # [doc = " sink types."] fn poll_flush_unpin (& mut self , cx : & mut Context < '_ >) -> Poll < Result < () , Self :: Error > > where Self : Unpin , { Pin :: new (self) . poll_flush (cx) } # [doc = " A convenience method for calling [`Sink::poll_close`] on [`Unpin`]"] # [doc = " sink types."] fn poll_close_unpin (& mut self , cx : & mut Context < '_ >) -> Poll < Result < () , Self :: Error > > where Self : Unpin , { Pin :: new (self) . poll_close (cx) } }
    };
}

SinkExt!()